function mySqrt(x) {
  let low = 0;
  let high = x;
  let answer = 0;
  while (low <= high) {
    const mid = low + Math.floor((high - low) / 2);
    if (mid * mid <= x) {
      answer = mid;                          // mid fits: remember it, then look for a bigger one
      low = mid + 1;
    } else {
      high = mid - 1;                        // mid is too big
    }
  }
  return answer;
}

